package org.apache.commons.codec.binary;

import java.io.*;
import java.math.*;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.codec.BinaryDecoder;
import org.apache.commons.codec.BinaryEncoder;
import org.apache.commons.codec.DecoderException;
import org.apache.commons.codec.EncoderException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for org.apache.commons.codec.binary.Base64 constructor.
 */
public class Base64_Base64_TriageGen2Test {

    @Test
    public void testDefaultConstructor() {
        // Testing public Base64() which calls this(false)
        Base64 base64 = new Base64();
        assertNotNull("Instance should not be null", base64);
        assertFalse("Default constructor should not be URL safe", base64.isUrlSafe());
    }

    @Test
    public void testBooleanConstructor() {
        // Testing public Base64(boolean urlSafe)
        Base64 urlSafeBase64 = new Base64(true);
        Base64 normalBase64 = new Base64(false);

        assertTrue("Constructor with true should be URL safe", urlSafeBase64.isUrlSafe());
        assertFalse("Constructor with false should not be URL safe", normalBase64.isUrlSafe());
    }

    @Test
    public void testLineLengthConstructor() {
        // Testing public Base64(int lineLength)
        int lineLength = 76;
        Base64 base64 = new Base64(lineLength);
        assertNotNull(base64);
        // Note: lineLength field is not directly accessible via getter in the provided signature, 
        // but we ensure the constructor executes without exception.
    }

    @Test
    public void testLineLengthAndSeparatorConstructor() {
        // Testing public Base64(int lineLength, byte[] lineSeparator)
        int lineLength = 64;
        byte[] lineSeparator = "\r\n".getBytes();
        Base64 base64 = new Base64(lineLength, lineSeparator);
        assertNotNull(base64);
    }

    @Test
    public void testAllArgsConstructor() {
        // Testing public Base64(int lineLength, byte[] lineSeparator, boolean urlSafe)
        int lineLength = 32;
        byte[] lineSeparator = "\n".getBytes();
        boolean urlSafe = true;
        Base64 base64 = new Base64(lineLength, lineSeparator, urlSafe);

        assertNotNull(base64);
        assertTrue("Should be URL safe as specified", base64.isUrlSafe());
    }
}
